export const WORD_BANK_SOUNDS = Object.keys(WORD_BANK);

export function wordsForSound(sound: string, position?: string): string[] {
  const s = (sound || "").replace(/\//g, "").toLowerCase();
  const bank = WORD_BANK[s];
  if (!bank) return [];
  if (position) {
    const p = position.toLowerCase() as WordPosition;
    return bank[p] || [];
  }
  return Array.from(new Set([...(bank.initial||[]), ...(bank.medial||[]), ...(bank.final||[])]));
}
